-- =============================================================================
-- Auto Business — Poorva-Shaap santaan rules + remedies (migration 026)
-- Brihat Parashara Hora Shastra, ch. 86 (Poorva-shaap-phaladhyaya): 105 santaan
-- rules across 13 categories + 10 traditional remedy categories. DB rows
-- override the baked ShaapData by rule_id; the engine auto-detects the
-- computable subset. Additive "शाप-दोष / सन्तान योग" prediction option.
-- TRADITIONAL/informational reference only — not medical/fertility advice.
-- Source: docs/Poorva_Shaap_Rules.md.
-- =============================================================================
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS shaap_rule (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    rule_id VARCHAR(16) NOT NULL,
    category VARCHAR(48) NOT NULL,
    ref VARCHAR(24) NOT NULL DEFAULT '',
    shaap_type VARCHAR(12) NOT NULL,         -- ashubh/mishrit/shubh
    rule_text TEXT NOT NULL,
    result_text TEXT NOT NULL,
    language VARCHAR(8) NOT NULL DEFAULT 'hi',
    updated_by_staff_id BIGINT UNSIGNED NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id), UNIQUE KEY uq_sr (rule_id, language), KEY idx_cat (category)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS shaap_remedy (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    category VARCHAR(48) NOT NULL,
    ref VARCHAR(24) NOT NULL DEFAULT '',
    upaay_text TEXT NOT NULL,
    language VARCHAR(8) NOT NULL DEFAULT 'hi',
    updated_by_staff_id BIGINT UNSIGNED NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id), UNIQUE KEY uq_srem (category, language)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE category=VALUES(category), ref=VALUES(ref), shaap_type=VALUES(shaap_type),
    rule_text=VALUES(rule_text), result_text=VALUES(result_text);

ON DUPLICATE KEY UPDATE ref=VALUES(ref), upaay_text=VALUES(upaay_text);

ON DUPLICATE KEY UPDATE cfg_value=VALUES(cfg_value);
