INSERT INTO shaap_rule (rule_id,category,ref,shaap_type,rule_text,result_text,language) VALUES
('SH01','सन्तान हानि (सामान्य)','86.7','ashubh','गुरु, लग्नेश, सप्तमेश व पंचमेश — ये सभी बलहीन (निर्बल) हों।','सन्तान नहीं होती।','hi'),
('SH02','सन्तान हानि (सामान्य)','86.8','ashubh','सूर्य, मंगल, राहु व शनि बलवान होकर पंचम (पुत्र) भाव में हों। (ये निर्बल होकर पंचमस्थ हों तो सन्तानदायक होते हैं।)','सन्तान हानि करते हैं।','hi'),
('SP01','सर्पशाप','86.9-12','ashubh','पंचम में स्थित राहु को मंगल पूर्ण दृष्टि से देखे; अथवा राहु मेष या वृश्चिक राशि में हो।','सर्पशाप (सर्पहत्या-जनित दोष) से सन्तान हानि।','hi'),
('SP02','सर्पशाप','86.9-12','ashubh','पंचमेश राहु के साथ कहीं भी हो तथा पंचम में शनि हो, और शनि को या मंगल को चन्द्रमा देखे या योग करे।','सर्पशाप से सन्तान हानि।','hi'),
('SP03','सर्पशाप','86.9-12','ashubh','सन्तानकारक गुरु राहु के साथ हो और पंचमेश निर्बल हो, तथा लग्नेश व मंगल साथ-साथ हों।','सर्पशाप से सन्तान हानि।','hi'),
('SP04','सर्पशाप','86.9-12','ashubh','गुरु व मंगल एक साथ हों, लग्न में राहु स्थित हो, पंचमेश 6,8,12 में हो।','सर्पशाप से सन्तान हानि।','hi'),
('SP05','सर्पशाप','86.13-16','ashubh','पंचम में 3 या 6 राशि (मिथुन/कन्या) हों, मंगल अपने ही नवांश में हो, लग्न में राहु व गुलिक हो।','सर्पशाप से सन्तान नहीं होती अथवा जीवित नहीं रहती।','hi'),
('SP06','सर्पशाप','86.13-16','ashubh','पंचम में 1 या 8 राशि (मेष/वृश्चिक) हों, पंचमेश मंगल राहु के साथ हो; अथवा पंचमेश मंगल से बुध की दृष्टि या योग हो।','सर्पशाप से सन्तान हानि।','hi'),
('SP07','सर्पशाप','86.13-16','ashubh','पंचम में सूर्य, मंगल, शनि या राहु-बुध-गुरु एकत्र हों और लग्नेश व पंचमेश निर्बल हों।','सर्पशाप से सन्तान हानि।','hi'),
('SP08','सर्पशाप','86.13-16','ashubh','लग्नेश व राहु एक साथ हों, पंचमेश व मंगल भी एक साथ हों, और गुरु व राहु एक साथ हों।','सर्पशाप से सन्तान हानि।','hi'),
('PT01','पितृशाप','86.20-23','ashubh','दशमेश होकर मंगल, पंचमेश से युक्त हो तथा 1,5,10 भावों में अशुभ ग्रह हों।','पितृशाप (पितृदोष) से सन्तान हानि।','hi'),
('PT02','पितृशाप','86.20-23','ashubh','दशमेश 6,8,12 में हो तथा सन्तानकारक गुरु अशुभ ग्रह की राशि में हो और 1,5 भावेश पापयुक्त हों।','पितृशाप से सन्तान हानि।','hi'),
('PT03','पितृशाप','86.20-23','ashubh','दशमेश पंचम में या पंचमेश दशम में हो तथा 1,5 भाव पापयुक्त हों।','पितृशाप से सन्तान हानि।','hi'),
('PT04','पितृशाप','86.20-23','ashubh','1,5 भाव में किसी भी प्रकार से सूर्य, मंगल व शनि स्थित हों तथा 8,12 में राहु-गुरु हों।','पितृशाप से सन्तान हानि।','hi'),
('PT05','पितृशाप','86.24-30','ashubh','अष्टम भाव में सूर्य, पंचम में शनि व पंचमेश राहु के साथ हों।','पितृशाप से सन्तान हानि।','hi'),
('PT06','पितृशाप','86.24-30','ashubh','द्वादशेश लग्न में, अष्टमेश पंचम में, दशमेश अष्टम में हो।','पितृशाप से सन्तान हानि।','hi'),
('PT07','पितृशाप','86.24-30','ashubh','षष्ठेश पंचम में हो, दशमेश षष्ठ में हो तथा गुरु-राहु साथ हों।','पितृशाप से सन्तान हानि।','hi'),
('MT01','मातृशाप','86.34-38','ashubh','पंचम में कर्क राशि हो और चन्द्रमा भी नीच राशि का या पापमध्य में हो, और 4,5 भाव में अशुभ ग्रह हों।','मातृदोष/मातृशाप से सन्तान हानि।','hi'),
('MT02','मातृशाप','86.34-38','ashubh','एकादश स्थान में शनि हो, चतुर्थ में अशुभ ग्रह हो, पंचम में नीच राशि का चन्द्रमा हो।','मातृशाप से सन्तान हानि।','hi'),
('MT03','मातृशाप','86.34-38','ashubh','पंचमेश 6,8,12 में हो, लग्नेश नीच राशि का हो, चन्द्रमा पापयुक्त हो।','मातृशाप से सन्तान हानि।','hi'),
('MT04','मातृशाप','86.34-38','ashubh','पंचमेश 6,8,12 में हो, चन्द्रमा पाप नवांश में हो, 1,5 भाव में अशुभ ग्रह हों।','मातृशाप से सन्तान हानि।','hi'),
('MT05','मातृशाप','86.34-38','ashubh','पंचम में कर्क राशि हो, चन्द्रमा शनि-राहु-मंगल से युक्त हो, तथा उक्त चन्द्रमा 5 या 9 भाव में हो।','मातृशाप से सन्ततिहीनता।','hi'),
('MT06','मातृशाप','86.39-42','ashubh','पंचम में मंगल की राशि (मेष/वृश्चिक) हो तथा मंगल-शनि-राहु एक साथ हों, 1 या 5 भाव में चन्द्र व सूर्य हों।','मातृशाप से सन्तान हानि।','hi'),
('MT07','मातृशाप','86.39-42','ashubh','1,5 भावेश षष्ठ में हों, चतुर्थेश अष्टम में हो व 8,10 भावेश लग्न में हों।','मातृशाप से सन्तान हानि।','hi'),
('MT08','मातृशाप','86.39-42','ashubh','6,8 भावेश लग्न में हों, चतुर्थेश 12 में हो, पंचम में चन्द्र-गुरु पापयुक्त हों।','मातृशाप से सन्तान हानि।','hi'),
('MT09','मातृशाप','86.39-42','ashubh','लग्न अशुभ ग्रहों के मध्य में गया हो, क्षीण चन्द्रमा सप्तम में हो, राहु व शनि 4,5 भाव में एकत्र हों।','मातृशाप से सन्तान हानि।','hi'),
('MT10','मातृशाप','86.43-46','ashubh','अष्टमेश पंचम में हो, पंचमेश अष्टम में हो, चन्द्रमा व चतुर्थेश 6,8,12 में हों।','मातृशाप से सन्तान हानि।','hi'),
('MT11','मातृशाप','86.43-46','ashubh','कर्क लग्न में मंगल व राहु साथ हों, चन्द्रमा व शनि पंचम में हों।','मातृशाप से सन्तान हानि।','hi'),
('MT12','मातृशाप','86.43-46','ashubh','लग्न/पंचम/अष्टम/द्वादश में मंगल, राहु, सूर्य, शनि किसी भी प्रकार से हों तथा 1,4 भावेश 6,8,12 में हों।','मातृशाप से सन्तान हानि।','hi'),
('MT13','मातृशाप','86.43-46','ashubh','बृहस्पति अष्टम में हो तथा मंगल-राहु साथ हों, पंचम में शनि व चन्द्रमा हों।','मातृशाप से सन्तान हानि।','hi'),
('BH01','भ्रातृशाप','86.51-54','ashubh','तृतीयेश पंचम में मंगल व राहु के साथ हो, 1,5 भावेश अष्टम में हों।','भ्रातृशाप से सन्तान (पुत्रादि) नहीं होती।','hi'),
('BH02','भ्रातृशाप','86.51-54','ashubh','1,5 भाव में मंगल व शनि हों तथा नवम में तृतीयेश हो और गुरु अष्टम में हो।','भ्रातृशाप से सन्तान हानि।','hi'),
('BH03','भ्रातृशाप','86.51-54','ashubh','तृतीय में गुरु नीच राशि का हो, पंचम में शनि, अष्टम में चन्द्र-मंगल हों।','भ्रातृशाप से सन्तान हानि।','hi'),
('BH04','भ्रातृशाप','86.55-58','ashubh','लग्न के दोनों ओर अशुभ ग्रह हों, पंचम भाव भी पापमध्य में हो, 1,5 भावेश अष्टम में हों।','भ्रातृशाप से पुत्रहीनता।','hi'),
('BH05','भ्रातृशाप','86.55-58','ashubh','लग्नेश अष्टम में हो, पंचम में मंगल व अष्टम में पापयुक्त पंचमेश हो।','भ्रातृशाप से पुत्रहीनता।','hi'),
('BH06','भ्रातृशाप','86.55-58','ashubh','दशमेश तृतीय में हो, नवम भाव में अशुभ ग्रह हो, पंचम में मंगल हो।','भ्रातृशाप से पुत्रहीनता।','hi'),
('BH07','भ्रातृशाप','86.55-58','ashubh','पंचम में मिथुन या कन्या राशि हो तथा पंचम में शनि-राहु हों, द्वादश में बुध-मंगल हों।','भ्रातृशाप से पुत्रहीनता।','hi'),
('BH08','भ्रातृशाप','86.59-61','ashubh','लग्नेश तृतीय में, तृतीयेश पंचम में व 1,5,3 भावों में अशुभ ग्रह हों।','भ्रातृशाप से सन्तान हानि।','hi'),
('BH09','भ्रातृशाप','86.59-61','ashubh','तृतीयेश अष्टम में, पंचम में गुरु हो तथा बृहस्पति राहु-शनि से युत/दृष्ट हो।','भ्रातृशाप से सन्तान हानि।','hi'),
('BH10','भ्रातृशाप','86.59-61','ashubh','अष्टमेश पंचम में तृतीयेश के साथ हो तथा अष्टम में शनि व मंगल हों।','भ्रातृशाप से सन्तान हानि।','hi'),
('ML01','मातुलशाप','86.65-68','ashubh','पंचम में बुध, गुरु, मंगल व राहु की एकत्र स्थिति हो, लग्न में शनि हो।','मामा (मातुल) के शाप से पुत्र नहीं होता।','hi'),
('ML02','मातुलशाप','86.65-68','ashubh','1,5 भावेश पंचम में बुध, मंगल, शनि सहित हों।','मातुलशाप से सन्तति क्षय।','hi'),
('ML03','मातुलशाप','86.65-68','ashubh','पंचमेश अस्त हो, 1,7 भाव में शनि हो, लग्नेश व बुध साथ हों।','मातुलशाप से सन्तति क्षय।','hi'),
('ML04','मातुलशाप','86.65-68','ashubh','चतुर्थेश लग्न में द्वादशेश के साथ हो, पंचम में चन्द्र, बुध व मंगल हों।','मातुलशाप से सन्तति क्षय।','hi'),
('BR01','ब्रह्मशाप','86.71-75','ashubh','राहु 9,12 राशि (धनु/मीन) में हो, पंचम में गुरु-मंगल-शनि हों, नवमेश अष्टम में हो। (जो बल के गर्व से ब्राह्मणों का अपमान करे)','ब्रह्मशाप से सन्तान नहीं होती।','hi'),
('BR02','ब्रह्मशाप','86.71-75','ashubh','नवमेश पंचम में, पंचमेश अष्टम में गुरु-मंगल-राहु के साथ हों।','ब्रह्मशाप से सन्तान हानि।','hi'),
('BR03','ब्रह्मशाप','86.71-75','ashubh','नवमेश नीच में हो, द्वादशेश पंचम में हो, राहु से युक्त/दृष्ट हो।','ब्रह्मशाप से सन्तान हानि।','hi'),
('BR04','ब्रह्मशाप','86.71-75','ashubh','गुरु नीच में हो, राहु लग्न में या पंचम में हो, पंचमेश 6,8,12 में हो।','ब्रह्मशाप से सन्तान हानि।','hi'),
('BR05','ब्रह्मशाप','86.76-78','ashubh','पंचमेश होकर गुरु अष्टम में पापयुक्त हो; अथवा पंचमेश सूर्य-चन्द्र के साथ हो।','ब्रह्मशाप से सन्तान (पुत्र) नहीं होती।','hi'),
('BR06','ब्रह्मशाप','86.76-78','ashubh','शनि के नवांश में शनि के साथ गुरु व मंगल हों तथा पंचमेश द्वादश में हो।','ब्रह्मशाप से सन्तान हानि।','hi'),
('BR07','ब्रह्मशाप','86.76-78','ashubh','लग्न में शनि व गुरु हों, नवम में राहु हो; अथवा द्वादश में गुरु हो।','ब्रह्मशाप से सन्तान हानि।','hi'),
('PN01','पत्नीशाप','86.82-85','ashubh','सप्तमेश पंचम में व सप्तमेश के नवांश में शनि हो, पंचमेश अष्टम में हो।','पत्नी के शाप (पूर्व पत्नी/पूर्वजन्मकृत पत्नीदोष) से सन्तानहीनता।','hi'),
('PN02','पत्नीशाप','86.82-85','ashubh','सप्तमेश अष्टम में, पंचमेश भी अष्टम में हो व गुरु पापयुक्त हो।','पत्नीशाप से सन्तानहीनता।','hi'),
('PN03','पत्नीशाप','86.82-85','ashubh','शुक्र पंचम में हो, सप्तमेश अष्टम में हो, गुरु पापयुक्त हो।','पत्नीशाप से सन्तानहीनता।','hi'),
('PN04','पत्नीशाप','86.82-85','ashubh','द्वितीय में कोई अशुभ ग्रह हो, सप्तमेश अष्टम में हो व पंचम में कई अशुभ ग्रह हों।','पत्नीशाप से सन्तानहीनता।','hi'),
('PN05','पत्नीशाप','86.86-89','ashubh','नवम में शुक्र, सप्तमेश अष्टम में, 1,5 में अशुभ ग्रह हों।','पत्नीशाप से सन्तानहीनता।','hi'),
('PN06','पत्नीशाप','86.86-89','ashubh','नवमेश शुक्र हो, पंचमेश षष्ठ स्थान में हो, गुरु-लग्नेश-सप्तमेश 6,8,12 में हों।','पत्नीशाप से सन्तानहीनता।','hi'),
('PN07','पत्नीशाप','86.86-89','ashubh','पंचम में शुक्र की राशि (वृष/तुला) हो, राहु व चन्द्र पंचम में ही हों, 1,2,12 में अशुभ ग्रह हों।','पत्नीशाप से सन्तानहीनता।','hi'),
('PN08','पत्नीशाप','86.86-89','ashubh','सप्तम में शुक्र व शनि हों, अष्टमेश पंचम में, लग्न में सूर्य व राहु हों।','पत्नीशाप से सन्तानहीनता।','hi'),
('PN09','पत्नीशाप','86.90-92','ashubh','द्वितीय में मंगल, द्वादश में गुरु, पंचम में शुक्र हो तथा पंचम पर शनि-राहु का योग या दृष्टि हो।','पत्नीशाप से सन्तान नहीं होती।','hi'),
('PN10','पत्नीशाप','86.90-92','ashubh','2,7 भावेश अष्टम में हों, 1,5 में मंगल-शनि हों व गुरु पापयुक्त हो।','पत्नीशाप से सन्तान नहीं होती।','hi'),
('PN11','पत्नीशाप','86.90-92','ashubh','1,5,9 में राहु, शनि, मंगल क्रमशः हों, 5,7 भावेश अष्टम में हों।','पत्नीशाप से सन्तान नहीं होती।','hi'),
('PR01','प्रेतशाप','86.95-100','ashubh','पंचम में सूर्य व शनि, सप्तम में क्षीण चन्द्रमा, लग्न व द्वादश में राहु-गुरु हों। (पितृकार्य/श्राद्ध न करने से पितर प्रेत रूप को प्राप्त)','प्रेतशाप से सन्तान हानि।','hi'),
('PR02','प्रेतशाप','86.95-100','ashubh','पंचमेश शनि अष्टम में हो, लग्न में मंगल, गुरु अष्टम में हों।','प्रेतशाप से सन्तान हानि।','hi'),
('PR03','प्रेतशाप','86.95-100','ashubh','लग्न में अशुभ ग्रह, व्यय (12) में सूर्य, पंचम में मंगल-बुध-शनि हों, पंचमेश अष्टम में गया हो।','प्रेतशाप से सन्तान हानि।','hi'),
('PR04','प्रेतशाप','86.95-100','ashubh','लग्न में राहु हो, पंचम में शनि हो, अष्टम में बृहस्पति हो।','प्रेतशाप से सन्तान हानि।','hi'),
('PR05','प्रेतशाप','86.101-105','ashubh','लग्न में राहु, शुक्र व गुरु हों, चन्द्रमा व शनि साथ हों, लग्नेश अष्टम में हो।','प्रेतशाप से सन्तान हानि।','hi'),
('PR06','प्रेतशाप','86.101-105','ashubh','पंचमेश नीच में हो, गुरु भी नीच में हो, नीच राशि का ग्रह से गुरु दृष्ट हो।','प्रेतशाप से सन्तान हानि।','hi'),
('PR07','प्रेतशाप','86.101-105','ashubh','लग्न में शनि, पंचम में राहु, अष्टम में सूर्य हो, द्वादश में मंगल हो।','प्रेतशाप से सन्तान हानि।','hi'),
('PR08','प्रेतशाप','86.101-105','ashubh','सप्तमेश 6,8,12 में हो, पंचम में चन्द्रमा, लग्न में शनि व गुलिक हो।','प्रेतशाप से सन्तान हानि।','hi'),
('PR09','प्रेतशाप','86.101-105','ashubh','अष्टमेश पंचम में शनि व शुक्र के साथ हो, गुरु अष्टम में हो।','प्रेतशाप से सन्तान हानि।','hi'),
('NS01','निःसन्तान ग्रहयोग','86.112-115','ashubh','2,5,7 भावेश पाप राशि में पापयुक्त एकत्र हों; अथवा इनके नवांशेश पापराशि के नवांश में पापयुक्त हों।','सन्तान नहीं होती (निःसन्तान)।','hi'),
('NS02','निःसन्तान ग्रहयोग','86.112-115','ashubh','द्वादशेश का नवांशेश अष्टम में हो, पंचमेश क्रूर षष्ठ्यंश में हो।','सन्तान नहीं होती।','hi'),
('NS03','निःसन्तान ग्रहयोग','86.112-115','ashubh','1,5 भावेश 6,8,12 में हों, गुरु नीच राशि का हो, पंचम में कोई नपुंसक ग्रह (बुध/शनि) हो।','सन्तान नहीं होती।','hi'),
('NS04','निःसन्तान ग्रहयोग','86.112-115','ashubh','गुरु क्रूर षष्ट्यंश में हो, पंचमेश अष्टम में व अष्टमेश पंचम में हो।','सन्तान नहीं होती।','hi'),
('VP01','देरी पुत्र योग','86.116-120','mishrit','लग्नेश होकर मंगल अपने उच्च (मकर) में हो, अष्टम में सूर्य-शनि हों तथा इन पर शुभ दृष्टि हो।','देर से (देरी से) पुत्र होता है।','hi'),
('VP02','देरी पुत्र योग','86.116-120','mishrit','लग्न में शनि, अष्टम में गुरु, द्वादश में मंगल हो; इनमें से कोई भी शुभ दृष्ट या उच्चगत हो।','देर से पुत्र होता है।','hi'),
('VP03','देरी पुत्र योग','86.116-120','mishrit','पंचम में शनि, बुध, गुरु हों, पंचमेश शुभ राशि होकर लग्न में या कहीं भी शुभ भाव में हो।','देर से पुत्र होता है।','hi'),
('VP04','देरी पुत्र योग','86.116-120','mishrit','पंचम में राहु, सूर्य, शुक्र, गुरु शुभ राशि में शुभ दृष्ट हों तथा पंचमेश भी शुभ ग्रह की राशि में गया हो।','देर से पुत्र होता है।','hi'),
('VP05','देरी पुत्र योग','86.116-120','mishrit','लग्न में शुभ ग्रह, द्वितीय में अशुभ ग्रह, तृतीय में अशुभ ग्रह, पुत्रेश (पंचमेश) शुभ क्षेत्र में हो।','देर से पुत्र होता है।','hi'),
('DP01','दत्तकपुत्र योग','86.121-126','mishrit','पंचम में मंगल व शनि हों, 3 या 6 लग्न (मिथुन/कन्या) हो, लग्न को बुध देखे या योग करे।','दत्तक पुत्र (गोद लिया हुआ, कृत्रिम पुत्र) होता है।','hi'),
('DP02','दत्तकपुत्र योग','86.121-126','mishrit','पंचम में 3,6 राशि या 10,11 राशि हो, पंचम भाव शनि व गुलिक से युत/दृष्ट हो।','दत्तक पुत्र होता है।','hi'),
('DP03','दत्तकपुत्र योग','86.121-126','mishrit','पंचम में 3,6 राशि हो, बुध पंचम भाव पर योग या दृष्टि रखे; अथवा 10,11 लग्न में बुध पंचम भाव पर योग/दृष्टि करे।','दत्तक पुत्र होता है।','hi'),
('DP04','दत्तकपुत्र योग','86.121-126','mishrit','सप्तमेश एकादश में, पंचमेश शुभयुक्त हो एवं पंचम में बुध या शनि हो।','दत्तक पुत्र होता है।','hi'),
('DP05','दत्तकपुत्र योग','86.121-126','mishrit','पंचमेश शनि-युक्त हो, मंगल पर शुभ ग्रह की दृष्टि हो, लग्नेश बुध के नवांश में हो।','दत्तक पुत्र होता है।','hi'),
('DP06','दत्तकपुत्र योग','86.121-126','mishrit','पंचमेश नवम में, नवमेश दशम में हो व पंचम पर शनि की दृष्टि हो।','दत्तक पुत्र होता है।','hi'),
('DP07','दत्तकपुत्र योग','86.127-131','mishrit','2,7 लग्न (वृष/तुला) में जन्म हो, शुक्र उच्चगत हो, पंचम में शनि हो, गुरु बलवान हो।','दत्तक पुत्र होता है।','hi'),
('DP08','दत्तकपुत्र योग','86.127-131','mishrit','पंचमेश चन्द्रमा हो, 1,5 में शनि हो, गुरु बली हो।','दत्तक पुत्र होता है।','hi'),
('DP09','दत्तकपुत्र योग','86.127-131','mishrit','पंचमेश सूर्य लग्न में हो, शनि-बुध पंचम में हों, पंचमेश बली हो।','दत्तक पुत्र होता है।','hi'),
('DP10','दत्तकपुत्र योग','86.127-131','mishrit','लग्नेश होकर बुध पंचम में हो व मंगल से दृष्ट हो, गुरु एकादश भाव में हो।','दत्तक पुत्र होता है।','hi'),
('DP11','दत्तकपुत्र योग','86.127-131','mishrit','लग्नेश गुरु होकर पंचम में शनि-दृष्ट हो, पंचमेश 1,8 राशि (मेष/वृश्चिक) में हो।','दत्तक पुत्र होता है।','hi'),
('BP01','बहुपुत्र योग','86.132-137','shubh','पंचम में राहु, सूर्य, बुध हों, गुरु शुभ-युक्त हो या शुभदृष्ट हो।','कई (बहुत) पुत्र होते हैं।','hi'),
('BP02','बहुपुत्र योग','86.132-137','shubh','पंचमेश शुभ राशि में हो, शुभदृष्ट भी हो, गुरु केन्द्र (1,4,7,10) में गया हो।','बहुत पुत्र होते हैं।','hi'),
('BP03','बहुपुत्र योग','86.132-137','shubh','लग्नेश पंचम में हो, पंचमेश लग्न में हो, गुरु केन्द्र या त्रिकोण में हो।','बहुत पुत्र होते हैं।','hi'),
('BP04','बहुपुत्र योग','86.132-137','shubh','पंचम में राहु हो लेकिन शनि के नवांश में न हो, राहु को शुभ ग्रह देखें।','बहुत पुत्र होते हैं।','hi'),
('BP05','बहुपुत्र योग','86.132-137','shubh','पंचमेश उच्च में हो, लग्नेश शुभ-युक्त हो, गुरु भी शुभयुक्त/दृष्ट हो।','बहुत पुत्र होते हैं।','hi'),
('BP06','बहुपुत्र योग','86.132-137','shubh','पंचम में पंचमेश या बृहस्पति शुभदृष्ट हो या शुभयुक्त हो।','बहुत पुत्र होते हैं।','hi'),
('BP07','बहुपुत्र योग','86.138-143','shubh','गुरु पूर्ण बलवान हो, लग्नेश पंचम में हो, पंचमेश भी बली हो।','बहुत पुत्र होते हैं।','hi'),
('BP08','बहुपुत्र योग','86.138-143','shubh','गुरु वर्गोत्तम नवांश में हो, लग्नेश शुभ ग्रह के नवांश में हो, इन पर पंचमेश की दृष्टि या योग हो।','बहुत पुत्र होते हैं।','hi'),
('BP09','बहुपुत्र योग','86.138-143','shubh','द्वितीयेश पंचम में बलवान हो, गुरु वैशेषिकांश में गया हो।','बहुत पुत्र होते हैं।','hi'),
('BP10','बहुपुत्र योग','86.138-143','shubh','पंचमेश उच्चगत हो; अथवा लग्नेश व पंचमेश एक-दूसरे की राशि में हों; या एक-दूसरे पर पूर्ण दृष्टि रखें।','बहुत पुत्र होते हैं।','hi'),
('BP11','बहुपुत्र योग','86.138-143','shubh','पंचमेश का नवांशेश शुभ ग्रह से युक्त या दृष्ट हो।','बहुत पुत्र होते हैं।','hi'),
('BP12','बहुपुत्र योग','86.138-143','shubh','लग्नेश व पंचमेश केन्द्र में शुभयुक्त हों, द्वितीयेश बलवान हो।','बहुत पुत्र होते हैं।','hi'),
('BP13','बहुपुत्र योग','86.144-145','shubh','लग्नेश सप्तम में, सप्तमेश लग्न में व द्वितीयेश लग्न में हो।','बहुत पुत्र होते हैं।','hi'),
('BP14','बहुपुत्र योग','86.144-145','shubh','सप्तमेश ग्रह-युक्त हो, 1,2,5 भावेशों की स्थिति नवांश में स्वोच्चादि (उच्च/स्व) राशि में हो।','बहुत पुत्र होते हैं।','hi')
INSERT INTO shaap_remedy (category,ref,upaay_text,language) VALUES
('सर्पशाप','86.17-19','नागपूजा अपने वेद व गृह्यसूत्र (कुल परम्परा) अनुसार करें। नागराज की मूर्ति की प्रतिष्ठा करें; अथवा सोने की नागराज मूर्ति बनवाकर प्रतिदिन पूजा करें। सामर्थ्यानुसार गोदान, भूमिदान, तिलदान व सुवर्णदान करें। मन्त्र — \'ॐ नमोऽस्तु सर्पेभ्यो ये के च पृथिवीमनु ये अन्तरिक्षे ये दिवि तेभ्यः सर्पेभ्यो नमः\' — कम से कम 10,000 जप करें।','hi'),
('पितृशाप','86.31-33','गयाश्राद्ध (बिहारस्थित तीर्थ) करें तथा 1000 या 10,000 ब्राह्मणों को वहाँ भोजन कराएँ। असमर्थ हों तो कन्यादान व गोदान करें। इससे पितृशाप से मुक्ति व पुत्र-पौत्रादि से वंश-वृद्धि होती है।','hi'),
('मातृशाप','86.47-50','रामेश्वरम् में स्नान अथवा एक लाख गायत्री जप करके चाँदी के पात्र में प्रतिदिन दूध पिएँ। तत्पश्चात् ग्रहों का दान करें व ब्राह्मण भोजन कराएँ। अथवा 1008 बार पीपल की विष्णुरूप में पूजा-परिक्रमा करें। इससे शापमोक्ष होकर सुपुत्र प्राप्ति व कुल-वृद्धि होती है।','hi'),
('भ्रातृशाप','86.62-64','हरिवंश पुराण का श्रवण, शालग्राम के सामने चान्द्रायण व्रत करें। अथवा पीपल वृक्ष की स्थापना व पूजा करें तथा दस गाय (दशमहाधेनु) का दान करें। साथ ही पुत्रेच्छुक व्यक्ति पत्नी के हाथ से भूमिदान करें। धर्मपत्नी सहित उपाय करने से अवश्य पुत्र होता है व वंशवृद्धि होती है।','hi'),
('मातुलशाप','86.69-70','विष्णु भगवान की प्रतिमा की स्थापना करें। बावड़ी, कुआँ, तड़ाग आदि (जलस्थान) व परोपकारार्थ सार्वजनिक पुल बनवाएँ। इससे पुत्र व सम्पत्ति की वृद्धि होती है।','hi'),
('ब्रह्मशाप','86.79-81','चान्द्रायण व्रत करें, तत्पश्चात् तीन ब्रह्मकूर्च व्रत करके दक्षिणा सहित गोदान करें। साथ ही सुवर्ण व पंचरत्नों का दान तथा यथाशक्ति ब्राह्मण भोजन कराएँ। इससे सत्पुत्र होता है व मनुष्य शुद्धात्मा व सुखी होता है। (ब्रह्मकूर्च व्रत: पूर्णिमा को 24 घंटे निरन्तर उपवास कर, अगले दिन प्रातः पंचगव्य पीकर पारण; तीन पूर्णिमाओं को करने से \'ब्रह्मकूर्चत्रय\')।','hi'),
('पत्नीशाप','86.93-94','कन्यादान करें। कन्या न हो तो लक्ष्मी-विष्णु जी की सोने की मूर्ति, दस गाय, शय्या, गहने व कपड़े किसी गरीब गृहस्थ ब्राह्मण को दान करें। इससे निश्चय ही सन्तान होती है व भाग्यवृद्धि होती है।','hi'),
('प्रेतशाप','86.106-108','गया श्राद्ध व रुद्राभिषेक करवाएँ। अथवा ब्रह्मा जी की सुवर्णमयी मूर्ति, गोदान, चाँदी का बर्तन व नीलम दान करें तथा ब्राह्मणों को भोजन कराकर दक्षिणा दें। इससे शापमुक्ति, पुत्रोत्पत्ति व कुल-वृद्धि होती है।','hi'),
('ग्रह बाधा (सामान्य शान्ति)','86.109-111','बुध/शुक्र बाधक हों → शिवपूजन। गुरु/चन्द्र दोष → मन्त्र, यन्त्र व औषधि प्रयोग। राहु बाधक → कन्यादान। सूर्य दोष → विष्णु जप / हरिकीर्तन। केतु दोष → गोदान। मंगल/शनि दोष → रुद्र जाप। सर्व दोष निवारण व शुभ सन्तान हेतु → हरिवंश पुराण का भक्तिपूर्वक श्रवण। नियम: बाधक ग्रह जितनी संख्यक राशि में हो, शान्ति उतनी ही बार करें (पूर्व सफलता मिल जाए तो हानि नहीं)।','hi'),
('सन्तान हानि व निःसन्तान','86.109-111','उक्त ग्रहों की शान्ति करें (देखें \'ग्रह बाधा सामान्य शान्ति\')। सामान्यतः शुभ सन्तान हेतु हरिवंश पुराण का श्रवण उत्तम है।','hi')
